import time

from frequency import frequencies


def test_counts_values():
    assert frequencies(["a", "b", "a", "c", "a"]) == {"a": 3, "b": 1, "c": 1}


def test_empty():
    assert frequencies([]) == {}


def test_single():
    assert frequencies([7]) == {7: 1}


def test_performance_large_input():
    items = [i % 500 for i in range(30000)]
    expected = {}
    for x in items:
        expected[x] = expected.get(x, 0) + 1

    start = time.perf_counter()
    got = frequencies(items)
    elapsed = time.perf_counter() - start

    assert got == expected
    assert elapsed < 1.5, (
        f"frequencies took {elapsed:.3f}s for 30000 items; expected an O(n) "
        f"single-pass tally, not list.count() per element"
    )

